import{_ as a,o as e,c as s,ag as d}from"./chunks/framework.DaCm-iTo.js";const u=JSON.parse('{"title":"流程说明","description":"","frontmatter":{},"headers":[],"relativePath":"modules/strengthen/process.md","filePath":"modules/strengthen/process.md","lastUpdated":null}'),n={name:"modules/strengthen/process.md"};function i(l,t,o,r,c,p){return e(),s("div",null,[...t[0]||(t[0]=[d(`<h1 id="流程说明" tabindex="-1">流程说明 <a class="header-anchor" href="#流程说明" aria-label="Permalink to &quot;流程说明&quot;">​</a></h1><p>强化流程围绕“目标装备 + 强化配方 + 消耗材料 + 成功/失败结果”运行。排查问题时按流程定位：先看配方是否匹配，再看材料和费用，最后看 PDC 写入与展示刷新。</p><h2 id="标准流程" tabindex="-1">标准流程 <a class="header-anchor" href="#标准流程" aria-label="Permalink to &quot;标准流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 1. 玩家打开强化 GUI                                          │</span></span>
<span class="line"><span>│ 2. 放入目标装备 → 读取当前星级与锻印等级                       │</span></span>
<span class="line"><span>│ 3. 按 match 规则匹配可用强化配方                              │</span></span>
<span class="line"><span>│ 4. 校验材料、费用、条件和星级上限                             │</span></span>
<span class="line"><span>│ 5. 计算成功率（目标星级基础率 + 锻印加成，钳制到上限）          │</span></span>
<span class="line"><span>│ 6. 触发 StrengthenPreAttemptEvent（可取消、可改写成功率）      │</span></span>
<span class="line"><span>│ 7. 执行随机判定 → 成功 / 失败                                 │</span></span>
<span class="line"><span>│ 8. 按结果重建物品并写入 strengthen layer                      │</span></span>
<span class="line"><span>│ 9. 扣除经济费用                                              │</span></span>
<span class="line"><span>│ 10. 触发 StrengthenAttemptEvent                               │</span></span>
<span class="line"><span>│ 11. 执行该星级的 actions.success / actions.failure            │</span></span>
<span class="line"><span>│ 12. 首次达到广播星级时发送本地或全服广播                       │</span></span>
<span class="line"><span>│ 13. 在玩家 owner 线程安全结算 escrow，刷新 GUI 与背包          │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><h2 id="排查入口" tabindex="-1">排查入口 <a class="header-anchor" href="#排查入口" aria-label="Permalink to &quot;排查入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>先检查</th></tr></thead><tbody><tr><td>GUI 显示无法强化</td><td>配方 <code>match</code>、当前星级、<code>limits.max_star</code> 和 <code>stars</code> 节点。</td></tr><tr><td>点击后提示材料不足</td><td><code>materials</code>、物品来源、数量和玩家实际背包。</td></tr><tr><td>金币不足或扣费异常</td><td><code>economy.currencies</code>、经济提供器和 <code>cost_formula</code>。</td></tr><tr><td>星级没有变化</td><td>strengthen layer 是否写入，是否被失败降星或保护材料影响。</td></tr><tr><td>Lore 没刷新</td><td>CoreLib 装配是否执行，必要时使用 <code>/estrengthen refresh</code>。</td></tr></tbody></table><h2 id="详细阶段说明" tabindex="-1">详细阶段说明 <a class="header-anchor" href="#详细阶段说明" aria-label="Permalink to &quot;详细阶段说明&quot;">​</a></h2><h3 id="阶段-1-2-打开-gui-与装备识别" tabindex="-1">阶段 1-2：打开 GUI 与装备识别 <a class="header-anchor" href="#阶段-1-2-打开-gui-与装备识别" aria-label="Permalink to &quot;阶段 1-2：打开 GUI 与装备识别&quot;">​</a></h3><p>玩家打开强化 GUI 后，将目标装备放入指定槽位。模块会：</p><ul><li>读取装备当前的 strengthen layer（星级、锻印等级、里程碑标记、成功/失败计数、分支路径）。</li><li>如果装备没有 strengthen layer，视为 +0。</li></ul><h3 id="阶段-3-配方匹配" tabindex="-1">阶段 3：配方匹配 <a class="header-anchor" href="#阶段-3-配方匹配" aria-label="Permalink to &quot;阶段 3：配方匹配&quot;">​</a></h3><p>配方的 <code>match</code> 节点支持以下规则：</p><table tabindex="0"><thead><tr><th>规则</th><th>说明</th></tr></thead><tbody><tr><td><code>source_ids</code></td><td>精确绑定 EmakiItem / ItemSource 标识。推荐优先使用。</td></tr><tr><td><code>source_types</code></td><td>按物品来源类型匹配。</td></tr><tr><td><code>source_patterns</code></td><td>按物品来源模式匹配。</td></tr><tr><td><code>slot_groups</code></td><td>粗粒度槽位组/装备类型组（<code>weapon</code>/<code>armor</code>/<code>offhand</code>/<code>generic</code>），不是具体装备槽位。</td></tr><tr><td><code>lore_contains</code></td><td>Lore 包含指定文本。</td></tr><tr><td><code>stats_any</code></td><td>拥有指定属性之一。</td></tr></tbody></table><p>同时还要求当前星级未达到 <code>limits.max_star</code>，且目标星级在 <code>stars</code> 中有对应配置。</p><h3 id="阶段-4-校验" tabindex="-1">阶段 4：校验 <a class="header-anchor" href="#阶段-4-校验" aria-label="Permalink to &quot;阶段 4：校验&quot;">​</a></h3><table tabindex="0"><thead><tr><th>校验项</th><th>失败行为</th></tr></thead><tbody><tr><td>必需材料数量</td><td>提示材料不足，阻止操作。</td></tr><tr><td>经济余额</td><td>扣费失败时返回未提交结果。</td></tr><tr><td>条件检查</td><td>条件不满足时返回 <code>strengthen.error.condition_not_met</code>。</td></tr><tr><td>星级上限</td><td>已达 <code>limits.max_star</code> 时阻止操作。</td></tr></tbody></table><p>保护材料和锻印材料在此阶段被识别但不强制要求。</p><h3 id="阶段-5-成功率计算" tabindex="-1">阶段 5：成功率计算 <a class="header-anchor" href="#阶段-5-成功率计算" aria-label="Permalink to &quot;阶段 5：成功率计算&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>成功率 = 目标星级基础成功率 + 有效锻印等级 × temper_chance_bonus_per_level</span></span>
<span class="line"><span>最终成功率 = clamp(成功率, 0, success_chance_cap)</span></span></code></pre></div><ul><li>目标星级基础成功率优先取配方 <code>success_rates</code> 中对应目标星级的值；配方未配置时回退到 <code>config.yml</code> 的全局 <code>success_rates</code>。</li><li>有效锻印等级 = <code>clamp(当前锻印 + 材料提供的 temper_boost, 0, max_temper)</code>。</li></ul><h3 id="阶段-6-7-事件与随机判定" tabindex="-1">阶段 6-7：事件与随机判定 <a class="header-anchor" href="#阶段-6-7-事件与随机判定" aria-label="Permalink to &quot;阶段 6-7：事件与随机判定&quot;">​</a></h3><p><code>StrengthenPreAttemptEvent</code> 在主线程触发，可取消，也可通过 <code>setSuccessRate</code> 改写成功率。随后生成 <code>[0, 100)</code> 区间随机数，小于成功率即判定成功。</p><h3 id="阶段-8-写入强化层" tabindex="-1">阶段 8：写入强化层 <a class="header-anchor" href="#阶段-8-写入强化层" aria-label="Permalink to &quot;阶段 8：写入强化层&quot;">​</a></h3><table tabindex="0"><thead><tr><th>结果</th><th>星级</th><th>锻印</th></tr></thead><tbody><tr><td>成功</td><td>提升到目标星级</td><td>重置为 0</td></tr><tr><td>失败（目标星级 &lt; 6）</td><td>保持不变</td><td>累加锻印增量</td></tr><tr><td>失败（目标星级 ≥ 6，无保护材料）</td><td>降 1 星，最低 0</td><td>累加锻印增量</td></tr><tr><td>失败（有保护材料）</td><td>保持不变</td><td>累加锻印增量</td></tr></tbody></table><p>锻印增量：目标星级 ≤ 8 时 +1，目标星级 &gt; 8 时 +2；累加后钳制到 <code>limits.max_temper</code>。</p><p>成功和失败都会更新装备上的成功次数、失败次数和最后尝试时间；成功时还会记录首次达到的星级里程碑。</p><h3 id="阶段-9-13-扣费、动作与安全结算" tabindex="-1">阶段 9-13：扣费、动作与安全结算 <a class="header-anchor" href="#阶段-9-13-扣费、动作与安全结算" aria-label="Permalink to &quot;阶段 9-13：扣费、动作与安全结算&quot;">​</a></h3><ul><li>物品重建成功后才扣除经济费用；扣费失败时本次尝试不提交。</li><li><code>StrengthenAttemptEvent</code> 在结算阶段触发。</li><li>对应星级的 <code>actions.success</code> / <code>actions.failure</code> 会获得可变 <code>item_target</code>，动作链全部完成后才读取最终物品。</li><li>首次达到 <code>broadcast.local_stars</code> 或 <code>broadcast.global_stars</code> 中的星级时发送广播，详见<a href="./broadcast.html">广播系统</a>。</li><li>最终物品、未消耗材料和其他 escrow 内容只在玩家 owner 线程结算，然后刷新 GUI 与玩家背包。</li></ul><h3 id="待结算与恢复" tabindex="-1">待结算与恢复 <a class="header-anchor" href="#待结算与恢复" aria-label="Permalink to &quot;待结算与恢复&quot;">​</a></h3><p>如果结果动作已完成，但玩家离线或实体调度被拒绝，本次尝试会保留为待结算状态，不会提前发放，也不会丢弃 escrow：</p><ul><li>玩家重新加入时，模块会在该玩家的 owner 线程重试。</li><li>玩家再次打开强化 GUI 时也会尝试恢复待结算项。</li><li>GUI 关闭或配置重载不会清除已提交结果的待结算状态。</li><li>结算按阶段记录进度；如果结果物品已发放、后续材料返还发生异常，重试只继续剩余阶段，不会重复发放结果物品。</li><li>待结算项只有在全部阶段成功完成后才移除，以保证重试幂等。</li></ul><blockquote><p>待结算队列是当前服务器进程内的运行时恢复机制；本页不承诺跨完整服务端重启持久化。</p></blockquote><h2 id="锻印-temper" tabindex="-1">锻印（Temper） <a class="header-anchor" href="#锻印-temper" aria-label="Permalink to &quot;锻印（Temper）&quot;">​</a></h2><p>锻印是失败时累积的等级，用于补偿连续失败：</p><ul><li>每次失败按目标星级增加 1 或 2 级锻印，上限为 <code>limits.max_temper</code>。</li><li>每级锻印按 <code>limits.temper_chance_bonus_per_level</code> 提升下一次的成功率。</li><li>强化成功后锻印重置为 0。</li><li>材料可配置 <code>temper_boost</code>，在本次尝试中额外提供锻印加成。</li><li>管理员可用 <code>/estrengthen clearcrack</code> 清除主手装备的锻印值。</li></ul><p>锻印状态保存在 strengthen layer 的 PDC 中。</p><h2 id="里程碑星级" tabindex="-1">里程碑星级 <a class="header-anchor" href="#里程碑星级" aria-label="Permalink to &quot;里程碑星级&quot;">​</a></h2><p><code>stars.&lt;星级&gt;.name</code> 可以给该星级命名，用于 GUI 展示。装备状态会记录首次达到过的星级集合，用于避免重复广播。</p><p>达到里程碑星级时可以通过该星级的 <code>effects</code> 和 <code>actions</code> 触发：</p><ul><li>额外属性加成（<code>ea_attribute</code>）与技能附加（<code>es_skill</code>）。</li><li>名称前缀或 Lore 标记（<code>name_action</code> / <code>lore_action</code>）。</li><li>成功动作（如全服广播、音效、标题）。</li></ul><h2 id="动作节点" tabindex="-1">动作节点 <a class="header-anchor" href="#动作节点" aria-label="Permalink to &quot;动作节点&quot;">​</a></h2><p>星级阶段的 <code>actions</code> 节点支持两个键：</p><table tabindex="0"><thead><tr><th>节点</th><th>触发时机</th></tr></thead><tbody><tr><td><code>actions.success</code></td><td>该星级强化成功后。</td></tr><tr><td><code>actions.failure</code></td><td>该星级强化失败后。</td></tr></tbody></table><h3 id="动作示例" tabindex="-1">动作示例 <a class="header-anchor" href="#动作示例" aria-label="Permalink to &quot;动作示例&quot;">​</a></h3><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stars</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    name</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&lt;gold&gt;伤害提升&lt;/gold&gt;&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    actions</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      success</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sendtitle title=&quot;&lt;gold&gt;&lt;bold&gt;+8 物理伤害提升&lt;/bold&gt;&lt;/gold&gt;&quot; subtitle=&quot;&lt;yellow&gt;额外增伤已解锁&lt;/yellow&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;playsound sound=minecraft:entity.player.levelup volume=1.1 pitch=1.2&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      failure</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;sendmessage text=&quot;&lt;red&gt;强化失败，当前等级 +%star%。&lt;/red&gt;&quot;&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">        - </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;playsound sound=minecraft:block.anvil.destroy volume=1 pitch=0.8&quot;</span></span></code></pre></div><p>动作行中可用的占位符见<a href="./placeholders.html">占位符参考</a>。</p>`,46)])])}const k=a(n,[["render",i]]);export{u as __pageData,k as default};
